function terminalSafe(value, l = 500) {
  const pieces = [];
  const sizes = [];
  let bytes = 0;
  let truncated = false;
  for (const character of String(value)) {
    let piece = character;
    if (UNSAFE_TERMINAL.test(character)) {
      const code = character.codePointAt(0);
      piece = code <= 0xff
        ? "\\x" + code.toString(16).padStart(2, "0")
        : "\\u" + code.toString(16).padStart(4, "0");
    }
    const size = Buffer.byteLength(piece, "utf8");
    if (bytes + size > l) { truncated = true; break; }
    pieces.push(piece);
    sizes.push(size);
    bytes += size;
  }
  if (!truncated) return pieces.join("");
  const markerBytes = Buffer.byteLength(TRUNCATION_MARKER, "utf8");
  while (pieces.length && bytes + markerBytes > l) {
    pieces.pop();
    bytes -= sizes.pop();
  }
  return pieces.join("") + TRUNCATION_MARKER;
}
